@page "/shipments"
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container">
    <div class="d-flex justify-content-between align-items-center mb-4">
        <h1>Shipments</h1>
        <button class="btn btn-success" @onclick="ShowCreateForm">+ New Shipment</button>
    </div>

    <div class="row mb-3">
        <div class="col-md-4">
            <label class="form-label">Filter by Status</label>
            <select class="form-select" @onchange="OnStatusFilterChanged">
                <option value="">All</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
        <div class="col-md-4">
            <label class="form-label">Search</label>
            <input type="text" class="form-control" placeholder="Tracking # or destination..."
                   @bind="searchTerm" @bind:event="oninput" @bind:after="FilterShipments" />
        </div>
    </div>

    @if (isCreating)
    {
        <div class="card mb-4">
            <div class="card-header">Create New Shipment</div>
            <div class="card-body">
                <div class="row g-3">
                    <div class="col-md-6">
                        <label class="form-label">Description</label>
                        <input type="text" class="form-control" @bind="newShipment.Description" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Customer Email</label>
                        <input type="email" class="form-control" @bind="newShipment.CustomerEmail" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Origin</label>
                        <input type="text" class="form-control" @bind="newShipment.Origin" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Destination</label>
                        <input type="text" class="form-control" @bind="newShipment.Destination" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Estimated Delivery</label>
                        <input type="date" class="form-control" @bind="estimatedDeliveryInput" />
                    </div>
                    <div class="col-12">
                        <button class="btn btn-primary me-2" @onclick="CreateShipment">Create</button>
                        <button class="btn btn-secondary" @onclick="CancelCreate">Cancel</button>
                    </div>
                </div>
            </div>
        </div>
    }

    @if (isLoading)
    {
        <p><em>Loading shipments...</em></p>
    }
    else if (filteredShipments is null || filteredShipments.Count == 0)
    {
        <p class="text-muted">No shipments found.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Tracking #</th>
                        <th>Description</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var shipment in filteredShipments)
                    {
                        <tr>
                            <td><code>@shipment.TrackingNumber</code></td>
                            <td>@shipment.Description</td>
                            <td>@shipment.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                            <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                            <td>
                                <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                        @onchange="e => UpdateStatus(shipment.Id, e)">
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@status" selected="@(status == shipment.Status)">@status</option>
                                    }
                                </select>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    private List<Shipment> allShipments = [];
    private List<Shipment> filteredShipments = [];
    private bool isLoading = true;
    private bool isCreating;
    private ShipmentStatus? statusFilter;
    private string searchTerm = string.Empty;
    private Shipment newShipment = new();
    private DateTime estimatedDeliveryInput = DateTime.Today.AddDays(5);

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        allShipments = await ShipmentService.GetShipmentsByStatusAsync(statusFilter);
        FilterShipments();
        isLoading = false;
    }

    private void FilterShipments()
    {
        filteredShipments = string.IsNullOrWhiteSpace(searchTerm)
            ? allShipments
            : allShipments.Where(s =>
                s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
              .ToList();
    }

    private async Task OnStatusFilterChanged(ChangeEventArgs e)
    {
        statusFilter = string.IsNullOrEmpty(e.Value?.ToString())
            ? null
            : Enum.Parse<ShipmentStatus>(e.Value.ToString()!);
        await LoadShipments();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            await LoadShipments();
        }
    }

    private void ShowCreateForm() => isCreating = true;
    private void CancelCreate() => isCreating = false;

    private async Task CreateShipment()
    {
        newShipment.EstimatedDelivery = estimatedDeliveryInput;
        newShipment.ShippedDate = DateTime.UtcNow;
        newShipment.Status = ShipmentStatus.Pending;
        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new();
        isCreating = false;
        await LoadShipments();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentStatus.Returned => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<div class="container">
    <h1 class="mb-4">Track Your Shipment</h1>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number..."
                       @bind="trackingNumber" @onkeydown="OnKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isSearching">
                    @if (isSearching)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Track
                </button>
            </div>
        </div>
    </div>

    @if (searched && shipment is null)
    {
        <div class="alert alert-warning">
            No shipment found with tracking number <strong>@searchedNumber</strong>. Please check the number and try again.
        </div>
    }
    else if (shipment is not null)
    {
        <div class="card">
            <div class="card-header">
                <h5 class="mb-0">Shipment <code>@shipment.TrackingNumber</code></h5>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Description</dt>
                            <dd>@shipment.Description</dd>
                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>
                            <dt>Destination</dt>
