@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<div class="container">
    <h1 class="mb-4">Track Your Shipment</h1>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number..."
                       @bind="trackingNumber" @onkeydown="OnKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isSearching">
                    @if (isSearching)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Track
                </button>
            </div>
        </div>
    </div>

    @if (searched && shipment is null)
    {
        <div class="alert alert-warning">
            No shipment found with tracking number <strong>@searchedNumber</strong>. Please check the number and try again.
        </div>
    }
    else if (shipment is not null)
    {
        <div class="card">
            <div class="card-header">
                <h5 class="mb-0">Shipment <code>@shipment.TrackingNumber</code></h5>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Description</dt>
                            <dd>@shipment.Description</dd>
                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>
                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>
                            <dt>Shipped Date</dt>
                            <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Status</dt>
                            <dd><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span></dd>
                            <dt>Estimated Delivery</dt>
                            <dd class="fs-5 fw-bold text-primary">
                                @(shipment.EstimatedDelivery?.ToString("MMMM dd, yyyy") ?? "TBD")
                            </dd>
                            @if (shipment.ActualDelivery.HasValue)
                            {
                                <dt>Delivered On</dt>
                                <dd class="text-success fw-bold">@shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</dd>
                            }
                        </dl>
                    </div>
                </div>

                <h6 class="mt-3">Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
